# group_by :: ['cat', 'car', 'dog', 'deer'], lambda s: s[0]
from collections import defaultdict

def group_by(items, key):
    out = defaultdict(list)
    for x in items:
        out[key(x)].append(x)
    return dict(out)

if __name__ == "__main__":
    print(group_by(['cat', 'car', 'dog', 'deer'], lambda s: s[0]))

